'use client';
import { useState } from 'react';
import { Building2, Plus, ShieldCheck, Trash2 } from 'lucide-react';
import { PageHeading, Modal } from '@/components/ui';
import { useSteward } from '@/components/store';
import { Vendor } from '@/lib/types';
import { money } from '@/lib/ledger';
export default function Vendors() {
 const { state,dispatch,canWrite,owner,trackVendor,loading,busy } = useSteward(); const [add,setAdd] = useState(false); const [remove,setRemove] = useState<Vendor | null>(null); const [error,setError] = useState(''); const [lookup,setLookup] = useState(''); const [tracking,setTracking] = useState(false);
 const vendors = state.vendors.filter(v => v.approved);
 return <><PageHeading eyebrow="TRUSTED PARTNERS" title="Good spending starts here." description="Control which vendors your agent can request expenses for." action={<button className="button primary" disabled={!canWrite || !owner} onClick={() => { setError(''); setAdd(true); }}><Plus size={17}/>Add vendor</button>}/><div className="info-strip"><ShieldCheck size={20}/><div><strong>{vendors.length} tracked approved vendors</strong><p>Approval is checked on-chain. The contract has no vendor-list method.</p></div></div><section className="panel lookup-panel"><form onSubmit={async e => { e.preventDefault(); setTracking(true); try { if(await trackVendor(lookup.trim())) setLookup(''); } finally { setTracking(false); } }}><label>Look up a vendor address<input required value={lookup} onChange={e => setLookup(e.target.value)} placeholder="G… or C…" maxLength={56}/></label><button className="button secondary" disabled={tracking || loading || busy}>{tracking ? 'Reading…' : 'Check approval'}</button></form><p className="form-note">Lookups only read approval status. Names and categories are local labels. This browser’s list is not a complete vendor registry.</p>{state.vendors.filter(v => !v.approved).map(v => <p className="form-note wrap" key={v.address}>{v.address}: not approved</p>)}</section><div className="vendor-grid">{vendors.map(v => <section key={v.address} className="panel vendor-card"><div className="vendor-card-top"><span className="vendor-avatar large">{v.name.slice(0,1)}</span><span className="badge approved"><span className="dot"/>Approved</span></div><h2>{v.name}</h2><p className="muted">{v.category} · local label</p><p className="mono vendor-id">{v.address}</p><div className="vendor-card-bottom"><div><small>Tracked committed spending</small><strong>{money(state.expenses.filter(e => e.vendor === v.address && e.status === 'Approved').reduce((s,e) => s + e.amount,0n))}</strong></div><button className="icon-button remove-button" disabled={!canWrite || !owner} aria-label={`Remove ${v.name}`} onClick={() => setRemove(v)}><Trash2 size={17}/></button></div></section>)}{!vendors.length && <div className="panel empty"><Building2/><p>No tracked approved vendors. Look up an address or add an approved vendor as the owner.</p></div>}</div>{add && <Modal title="Approve a vendor" close={() => setAdd(false)}><p className="muted">Only the contract owner can change vendor approval.</p><form onSubmit={async e => { e.preventDefault(); const d = new FormData(e.currentTarget); const address = String(d.get('address')).trim(); setError(''); if(state.vendors.some(v => v.address === address && v.approved)) { setError('This vendor is already approved.'); return; } if(await dispatch({ function:'set_vendor',vendor:{ address,name:String(d.get('name')).trim(),category:String(d.get('category')).trim(),approved:true },approved:true })) setAdd(false); }}><label>Vendor name (local label)<input name="name" required maxLength={80} placeholder="e.g. Slack"/></label><label>Category (local label)<input name="category" required maxLength={60} placeholder="e.g. Collaboration"/></label><label>Stellar vendor address<input name="address" required maxLength={56} placeholder="G… or C…"/></label><p className="form-note">The contract stores only the vendor address and approval. Names and categories stay in this browser.</p>{error && <p className="form-error" role="alert">{error}</p>}<button className="button primary" disabled={!canWrite || !owner}>Sign vendor approval</button></form></Modal>}{remove && <Modal title={`Remove ${remove.name}?`} close={() => setRemove(null)}><p className="muted">New requests and approvals for this vendor will be blocked. Existing pending reservations remain until rejected or cancelled. Approved commitments remain accounted for.</p><div className="modal-actions"><button className="button secondary" onClick={() => setRemove(null)}>Keep vendor</button><button className="button danger" disabled={!canWrite || !owner} onClick={async () => { if(await dispatch({ function:'set_vendor',vendor:remove,approved:false })) setRemove(null); }}>Sign vendor removal</button></div></Modal>}</>;
}
